models={}
def model(module,prefix,title):
 models[module]={'version':'2026.10.1','title':title,'prefix':prefix,'groups':[]}
 return models[module]
def group(m,n,title,kind,owner,accountable,inputs,exclusions,risks):
 g={'code':f"{m['prefix']}.{n:02d}",'title':title,'kind':kind,'owner':owner,'accountable':accountable,'inputs':inputs,'exclusions':exclusions,'risks':risks,'packages':[]};m['groups'].append(g);return g
def packages(g,text):
 # title | deliverable 1 | acceptance 1 | deliverable 2 | acceptance 2 | duration
 for i,line in enumerate(text.strip().splitlines(),1):
  title,d1,c1,d2,c2,days=[x.strip() for x in line.split('|')]
  g['packages'].append({'code':f"{g['code']}.{i:02d}",'title':title,'scope':f"Produção e conferência de {d1.lower()} e {d2.lower()}, com autoria, revisão e rastreabilidade das premissas.",'acceptance':f"{c1}. {c2}. Responsável pelo aceite registra a decisão e a versão das evidências.",'duration':int(days),'weight':1,'dependencies':[], 'deliverables':[{'id':'D1','title':d1,'criterion':c1,'required':True,'checked':False,'evidence':''},{'id':'D2','title':d2,'criterion':c2,'required':True,'checked':False,'evidence':''}]})
